const input = $('When Executed by Another Workflow').first().json;
const rawOutput = $input.first().json;

// Extract text from OpenAI response
let responseText = '';
if (rawOutput.message && rawOutput.message.content) {
  responseText = rawOutput.message.content;
} else if (rawOutput.choices && rawOutput.choices[0]) {
  responseText = rawOutput.choices[0].message.content;
} else if (typeof rawOutput === 'string') {
  responseText = rawOutput;
} else {
  responseText = JSON.stringify(rawOutput);
}

// Parse JSON response from LLM
let reply = '';
let updated_short_memory = '';
let kb_hit = false;

try {
  let jsonStr = responseText;
  const jsonMatch = responseText.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) jsonStr = jsonMatch[1].trim();
  const objMatch = jsonStr.match(/\{[\s\S]*\}/);
  if (objMatch) jsonStr = objMatch[0];

  const parsed = JSON.parse(jsonStr);
  reply = parsed.response_text || '';
  updated_short_memory = parsed.updated_short_memory || '';
  kb_hit = parsed.kb_hit || false;
} catch (e) {
  // Fallback based on intent
  const intent = input.intent || 'unknown';
  if (intent === 'greeting') {
    reply = 'Hola, te ayudaré a encontrar info, ¿qué buscas?';
  } else if (intent === 'human_handoff') {
    reply = 'Entendido. Lo paso con una persona.';
  } else if (intent === 'unsupported') {
    reply = 'Por ahora solo puedo ayudarte con mensajes de texto.';
  } else {
    reply = 'No estoy seguro de haber entendido bien. ¿Me lo puedes escribir con un poco más de detalle?';
  }
  updated_short_memory = 'Error parsing LLM reply, fallback used';
  kb_hit = false;
}

// Safety: ensure no empty reply
if (!reply.trim()) {
  reply = 'No estoy seguro de haber entendido bien. ¿Me lo puedes escribir con un poco más de detalle?';
}

return [{ json: { response_text: reply, updated_short_memory, kb_hit } }];
